import React,{useState,useEffect} from 'react';
import './style.css';
const initial=[42,19,73,28,61,35,87,12,54,46];
export default function App(){
 const [values,setValues]=useState(initial),[i,setI]=useState(1),[j,setJ]=useState(1),[playing,setPlaying]=useState(false),[speed,setSpeed]=useState(500);
 const step=()=>{if(i>=values.length){setPlaying(false);return;}if(j>0&&values[j]<values[j-1]){const a=[...values];[a[j],a[j-1]]=[a[j-1],a[j]];setValues(a);setJ(j-1);}else{setI(i+1);setJ(i+1);}};
 useEffect(()=>{if(!playing)return;const t=setTimeout(step,speed);return()=>clearTimeout(t)},[playing,i,j,values,speed]);
 const reset=()=>{setValues(initial);setI(1);setJ(1);setPlaying(false)};
 return <main><div className="eyebrow">ALGORITHM LAB</div><h1>Insertion sort</h1><p>Grow a sorted prefix, one comparison at a time.</p><div className="bars" aria-label="Sorting values">{values.map((v,k)=><div className={'bar '+(k===j?'active':k<i?'sorted':'')} key={k} style={{height:(v*2.1)+'px'}}><span>{v}</span></div>)}</div><div className="controls"><button onClick={()=>setPlaying(!playing)} disabled={i>=values.length}>{playing?'Pause':'Play'}</button><button onClick={step} disabled={playing||i>=values.length}>Step</button><button onClick={reset}>Reset</button><label>Speed<input aria-label="Animation speed" type="range" min="100" max="1000" value={1100-speed} onChange={e=>setSpeed(1100-Number(e.target.value))}/></label></div><output>{i>=values.length?'Sorted':`Sorted prefix: ${i} of ${values.length}`}</output></main>
}
